<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content publishx-scope"><div class="panel_s"><div class="panel-body"><h3>Blogging Settings</h3><?php echo form_open(admin_url('publishx/settings')); ?><?php echo render_input('publishx_blog_title','Blog title',get_option('publishx_blog_title')); ?><?php echo render_textarea('publishx_blog_description','Blog description',get_option('publishx_blog_description')); ?><?php echo render_select('publishx_default_language',[['id'=>'English','name'=>'English'],['id'=>'Spanish','name'=>'Spanish']],['id','name'],'Default language',get_option('publishx_default_language')); ?><?php echo render_select('publishx_logo_source',[['id'=>'website','name'=>'Use website logo'],['id'=>'crm','name'=>'Use CRM logo'],['id'=>'custom','name'=>'Custom logo']],['id','name'],'Logo source',get_option('publishx_logo_source')); ?><?php echo render_select('publishx_favicon_source',[['id'=>'website','name'=>'Use website favicon'],['id'=>'crm','name'=>'Use CRM favicon'],['id'=>'custom','name'=>'Custom favicon']],['id','name'],'Favicon source',get_option('publishx_favicon_source')); ?><div class="checkbox checkbox-primary"><input type="hidden" name="publishx_use_crm_openai_key" value="0"><input type="checkbox" name="publishx_use_crm_openai_key" value="1" <?php echo get_option('publishx_use_crm_openai_key')==='1'?'checked':''; ?>><label>Use the OpenAI key already configured in the CRM</label></div><?php echo render_input('publishx_openai_key','Module OpenAI key fallback',get_option('publishx_openai_key'),'password'); ?><?php echo render_input('publishx_ga_measurement_id','Default GA4 Measurement ID',get_option('publishx_ga_measurement_id')); ?><button class="btn btn-primary pull-right">Save Settings</button><?php echo form_close(); ?></div></div></div></div><?php init_tail(); ?></body></html>